tests/js/helpers/load.js.excerpt:
1: import fs from "node:fs";
2: import path from "node:path";
3: import { fileURLToPath } from "node:url";
4: import { vi } from "vitest";
5: 
6: // Resolve via path, not `new URL(relative, base)` — in the jsdom test
7: // environment the global URL is jsdom's and rejects file-scheme resolution.
8: const JS_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../../src/crud_views/static/crud_views/js");
9: 
10: // jsdom's window.location is unforgeable (cannot be spied on or replaced) and
11: // its navigation methods are no-ops. The shipped files always navigate via
12: // `globalThis.location.*`, so loadScript executes them against a Proxy (bound
13: // as both `window` and `globalThis`) whose `location` is this stub; everything
14: // else falls through to the real window.
15: export const nav = {
16:     assign: vi.fn(),
17:     href: "",
18: };
19: 
20: export function resetNav() {
21:     nav.assign = vi.fn();
22:     nav.href = "";
23: }
24: 
25: function testWindow() {
26:     return new Proxy(window, {
27:         get: (target, prop) => (prop === "location" ? nav : Reflect.get(target, prop)),
28:         set: (target, prop, value) => Reflect.set(target, prop, value),
29:     });
30: }
31: 
32: export async function loadScript(name) {
33:     const code = fs.readFileSync(path.join(JS_DIR, `${name}.js`), "utf-8");
34:     const win = testWindow();
35:     // Evaluates the package's own static JS inside the test window, as a <script> tag would.
36:     new Function("window", "globalThis", code)(win, win); // NOSONAR S1523
37:     // No shipped script queues its start-up on jQuery's ready any more (formset.js starts on
38:     // DOMContentLoaded / readyState), so wiring is complete when the evaluation returns. The
39:     // function stays async so callers keep awaiting it.
40: }

